import java.util.Scanner;

public class Main {
    static long total_moves = 0;

    static int countDigitsInNumber(long n) {
        int count = 0;
        while (n > 0) {
            n /= 10;
            count++;
        }
        return count;
    }

    static long getNumberThreshold(long n) {
        int digits = countDigitsInNumber(n);
        long threshold = 0;
        long base_power = 1;
        for (int i = 0; i < digits; i++) {
            threshold += base_power;
            base_power *= 10;
        }
        if (threshold <= n) return threshold;
        return (threshold - 1) / 10;
    }

    static long recursiveProcess(long n) {
        if (n <= 6) return n;
        if (n <= 11) return 13 - n;
        long base_num = getNumberThreshold(n);
        long limit = base_num * 10 + 1;
        if (n % base_num == 0) {
            long quotient = n / base_num;
            if (n <= limit / 2 + base_num) return countDigitsInNumber(base_num) * quotient;
            else {
                long diff = recursiveProcess(limit - n);
                return countDigitsInNumber(limit) + diff;
            }
        } else {
            long lower_bound = (n / base_num) * base_num;
            long upper_bound = (n / base_num + 1) * base_num;
            long res = recursiveProcess(lower_bound) + recursiveProcess(n - lower_bound);
            if (n > limit / 2) {
                long temp1 = recursiveProcess(lower_bound) + recursiveProcess(n - lower_bound);
                long temp2 = countDigitsInNumber(limit) + recursiveProcess(limit - n);
                res = Math.min(temp1, temp2);
            }
            return res;
        }
    }

    public static void main(String[] args) {
